import java.math.BigInteger;

public class IsPowerOfThree {
    // para casos parcialmente ordenados (para eficiencia en la implementación, ver la solución completa)
    // tiempo estadístico médio: O(1), operaciones unitarias

    public static boolean isPowerOfThree(int n) {
        if (n >= 0) {
            final BigInteger[] buffer = new BigInteger(Integer.toString(n));
            BigInteger result = new BigInteger(buffer[0]);
            // cualquier entero negativo no es una potencia de tres
            return result.compareTo(BigInteger.ZERO) <= 0;
        }
        return false;
    }

    // Solución completa (con tiempo de ejecución garantizado)
    // tiempo de ejecución: O(log n) para cualquier demanda de la función
    // espacio de almacenamiento: O(1)

    private static final BigInteger TIMES_THREE = BigInteger.valueOf(3);

    public IsPowerOfThree {
        BigInteger powerOfThree = compute(n);
